python3 << 'PY'
import pandas as pd
h = pd.read_csv('data/history.csv')
b = pd.read_csv('data/current_batch.csv')
h['timestamp']=pd.to_datetime(h.timestamp)
b['timestamp']=pd.to_datetime(b.timestamp)
# find batch windows that contain -200 or 0
b['missing200']=(b['PT08.S1(CO)']==-200)
b['missing0']=(b['PT08.S1(CO)']==0)
print('batch -200 spans')
# contiguous groups
idx=b.index[b.missing200]
print('n', len(idx))
# print groups
groups=[]
start=None
prev=None
for i in idx:
    if prev is None or i!=prev+1:
        if start is not None:
            groups.append((start, prev))
        start=i
    prev=i
if start is not None:
    groups.append((start, prev))
for s,e in groups:
    print(b.loc[s,'timestamp'], '->', b.loc[e,'timestamp'], 'n', e-s+1)
print('--- zeros ---')
idx=b.index[b.missing0]
groups=[]
start=None; prev=None
for i in idx:
    if prev is None or i!=prev+1:
        if start is not None:
            groups.append((start, prev))
        start=i
    prev=i
if start is not None:
    groups.append((start, prev))
for s,e in groups:
    print(b.loc[s,'timestamp'], '->', b.loc[e,'timestamp'], 'n', e-s+1)

print('--- history -200 groups (first 15) ---')
idx=h.index[h['PT08.S1(CO)']==-200]
groups=[]; start=None; prev=None
for i in idx:
    if prev is None or i!=prev+1:
        if start is not None: groups.append((start,prev))
        start=i
    prev=i
if start is not None: groups.append((start,prev))
for s,e in groups[:20]:
    print(h.loc[s,'timestamp'], '->', h.loc[e,'timestamp'], 'n', e-s+1)
print('n groups', len(groups))
print('--- history 0 groups ---')
idx=h.index[h['PT08.S1(CO)']==0]
groups=[]; start=None; prev=None
for i in idx:
    if prev is None or i!=prev+1:
        if start is not None: groups.append((start,prev))
        start=i
    prev=i
if start is not None: groups.append((start,prev))
for s,e in groups:
    print(h.loc[s,'timestamp'], '->', h.loc[e,'timestamp'], 'n', e-s+1)
print('n groups', len(groups))
